// Runtime SVG string for JS-injected markup (script blocks cannot use
// the Icon.astro component). Mirrors Icon.astro's output exactly.
export function iconSvg(name: IconName, size = 16): string {
  return `<svg width="${size}" height="${size}" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true">${ICON_PATHS[name]}</svg>`;
}
